/**
 * Enemy animation audit: checks the supplied pack (`assets-src/enemy-animations/<id>.png`, `manifest.json` version 2:
 * one grid per type, a clip per row) and every game sheet in public/assets/enemy-animations/ (generated by
 * `scripts/normalize-enemy-animations.ts`) against the animation registry (`src/render/enemy-animations.ts`).
 * No browser and no dependency (`scripts/png.ts`).
 *
 *   npx vite-node scripts/audit-enemy-animations.ts            # per-clip table and warnings; exit code 1 on errors
 *   npx vite-node scripts/audit-enemy-animations.ts -- --frames # one line per frame as well
 *   npx vite-node scripts/audit-enemy-animations.ts -- --write  # regenerate src/render/enemy-animation-bounds.ts
 *
 * Source: every declared sheet exists, is a PNG and is `columns` × `rows` cells; the cells after each clip's frames
 * are empty. Game sheets per clip: visible bounds (alpha > 16) as a share of the cell, centre of those bounds (share of
 * the cell edge from its middle, +x forward), coverage, the visible share of the cell's 1 px border (art cut by the
 * edge, bleeding from a neighbouring cell, a grid line), the largest frame-to-frame jump of the alpha-weighted centre
 * (pivot drift) and of the visible size, the loop seam (last → first frame) and the smallest share of pixels that
 * change between neighbouring frames (a frozen clip). Errors: a missing or undecodable file, a wrong grid, a blank
 * frame, no alpha, a cut body, a pivot jump in a loop, a drawn unused cell. Warnings are for review by eye
 * (`/gallery.html?anim`).
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { DEFAULT_CONTENT } from "../src/content";
import type { EnemyId } from "../src/core/types";
import {
  ANIMATION_COLUMNS,
  ANIMATION_MANIFEST as manifest,
  ANIMATION_ROWS,
  ANIMATION_STATES,
  clipError,
  ENEMY_ANIMATIONS,
  manifestClips,
  missionAnimationTypes,
  sheetFrame,
} from "../src/render/enemy-animations";
import { artFor, artUrl } from "../src/render/enemy-art";
import { artSignature, decodePng, identify, IDENTITY_MARGIN, measureArt, VISIBLE_ALPHA, type ArtMetrics, type Png } from "./png";

const ROOT = new URL("../", import.meta.url),
  BOUNDS_FILE = new URL("../src/render/enemy-animation-bounds.ts", import.meta.url);
const args = process.argv.slice(2);

/** Pivot drift between neighbouring loop frames (share of the cell) worth a look; above `DRIFT_ERROR` it jumps. */
const DRIFT_WARN = 0.03,
  DRIFT_ERROR = 0.08;
/** Change of the visible longest side between neighbouring frames (share) worth a look. */
const SIZE_WARN = 0.12;
/** Visible share of the cell border above which a frame counts as cut. */
const EDGE_ERROR = 0.08;

const errors: string[] = [],
  warnings: string[] = [],
  identities: string[] = [];
const f2 = (v: number) => (v >= 0 ? " " : "") + v.toFixed(2);

/** Cell `f` (row by row) of a grid with `columns` cells per row, as an image of its own. */
function cell(png: Png, f: number, w: number, h: number, columns: number): Png {
  const x0 = (f % columns) * w,
    y0 = Math.floor(f / columns) * h,
    rgba = new Uint8Array(w * h * 4);
  for (let y = 0; y < h; y++) rgba.set(png.rgba.subarray(((y0 + y) * png.width + x0) * 4, ((y0 + y) * png.width + x0 + w) * 4), y * w * 4);
  return { ...png, width: w, height: h, rgba };
}
function visibleBorder({ width: w, height: h, rgba }: Png) {
  let n = 0;
  for (let x = 0; x < w; x++) for (const y of [0, h - 1]) if (rgba[(y * w + x) * 4 + 3] > VISIBLE_ALPHA) n++;
  for (let y = 1; y < h - 1; y++) for (const x of [0, w - 1]) if (rgba[(y * w + x) * 4 + 3] > VISIBLE_ALPHA) n++;
  return n / (2 * (w + h) - 4);
}
/** Share of pixels whose alpha differs by more than 24 between two cells. */
function changed(a: Png, b: Png) {
  let n = 0;
  for (let i = 3; i < a.rgba.length; i += 4) if (Math.abs(a.rgba[i] - b.rgba[i]) > 24) n++;
  return n / (a.width * a.height);
}
const longest = (m: ArtMetrics) => Math.max(m.visibleWidth, m.visibleHeight);
const load = (path: URL, what: string) => {
  try {
    return decodePng(readFileSync(path));
  } catch (e) {
    errors.push(`${what}: ${(e as Error).message}`);
    return undefined;
  }
};

// The supplied pack: version, grid, nothing drawn after each clip's frames, and the identity of every sheet: its idle
// frames must look most like its own enemy's static art of all the roster's (the first pack shipped ten sheets
// under each other's names). A disabled entry is checked as well, so the reason it stays out remains visible.
if (manifest.version !== 2) errors.push(`manifest version ${manifest.version}: expected 2 (one grid per enemy)`);
const statics = new Map(
  Object.keys(DEFAULT_CONTENT.enemies).flatMap((id) => {
    const art = artFor(id as EnemyId);
    return art ? [[id, artSignature(decodePng(readFileSync(new URL(`public/${artUrl(art, "")}`, ROOT))))] as const] : [];
  }),
);
for (const [id, entry] of Object.entries(manifest.enemies)) {
  if (!DEFAULT_CONTENT.enemies[id]) errors.push(`${id}: in the manifest but not an enemy type`);
  if (!artFor(id as EnemyId)) errors.push(`${id}: no static art to fall back to`);
  if (entry.disabled) warnings.push(`${id}: disabled in the manifest (${entry.disabled}); it shows its static art`);
  const png = load(new URL(entry.sheet, ROOT), `source ${id}`);
  if (!png) continue;
  if (png.width !== manifest.frameWidth * manifest.columns || png.height !== manifest.frameHeight * manifest.rows) {
    errors.push(`source ${id}: ${png.width}×${png.height} is not ${manifest.columns}×${manifest.rows} cells of ${manifest.frameWidth}×${manifest.frameHeight}`);
    continue;
  }
  const clips = manifestClips(entry);
  for (const [state, a] of Object.entries(clips))
    for (let i = a.frames; i < manifest.columns; i++)
      if (measureArt(cell(png, a.row * manifest.columns + i, manifest.frameWidth, manifest.frameHeight, manifest.columns)).coverage > 0) warnings.push(`source ${id}/${state}: unused cell ${i + 1} is drawn`);
  const idle = clips.idle ?? Object.values(clips)[0];
  if (!idle) continue;
  const ranked = identify(
      Array.from({ length: Math.ceil(idle.frames / 2) }, (_, i) => cell(png, idle.row * manifest.columns + i * 2, manifest.frameWidth, manifest.frameHeight, manifest.columns)),
      statics,
    ),
    [best, second] = ranked,
    own = ranked.find((r) => r.id === id);
  identities.push(`${id.padEnd(12)} ${best.id === id ? "ok  " : "BAD "} closest ${best.id} ${best.distance.toFixed(3)}, next ${second.id} ${second.distance.toFixed(3)}${best.id === id ? "" : `, own ${own?.distance.toFixed(3)} (rank ${ranked.indexOf(own!) + 1})`}`);
  if (best.id !== id) errors.push(`${id}: ${entry.sheet} looks like ${best.id} (${best.distance.toFixed(3)}), not ${id} (rank ${ranked.indexOf(own!) + 1}); verify by eye and rename or disable it`);
  else if (best.distance / second.distance > IDENTITY_MARGIN) warnings.push(`${id}: identity is close to ${second.id} (${best.distance.toFixed(3)} vs ${second.distance.toFixed(3)}); confirm by eye`);
}
// Coverage: every enabled manifest entry is registered (the registry reads the manifest), and every game sheet in
// public/ belongs to a registered type (a leftover or unnormalized sheet there would be shipped but never shown).
const registered = Object.keys(ENEMY_ANIMATIONS) as EnemyId[];
for (const file of readdirSync(new URL("public/assets/enemy-animations/", ROOT)))
  if (!registered.includes(file.replace(/\.png$/, "") as EnemyId)) errors.push(`public/assets/enemy-animations/${file}: not a registered sheet (unnormalized, disabled or stray)`);

const union: Partial<Record<EnemyId, { x0: number; y0: number; x1: number; y1: number; size: number }>> = {};
let decoded = 0,
  stored = 0;
console.log("clip            frames  cell     visible W×H (avg)  ctr x  ctr y  cover  edge    max drift  max size  seam   min change");
for (const id of registered) {
  const set = ENEMY_ANIMATIONS[id]!,
    first = ANIMATION_STATES.map((s) => set[s]).find(Boolean)!,
    path = new URL(`public/${first.path}`, ROOT),
    png = load(path, `${id}: ${first.path}`);
  if (!png) continue;
  stored += readFileSync(path).length;
  decoded += png.width * png.height * 4;
  if (png.colorType !== 6) errors.push(`${id}: no alpha channel (colour type ${png.colorType})`);
  if (png.width !== first.frameWidth * ANIMATION_COLUMNS || png.height !== first.frameHeight * ANIMATION_ROWS)
    errors.push(`${id}: sheet ${png.width}×${png.height} is not ${ANIMATION_COLUMNS}×${ANIMATION_ROWS} cells of ${first.frameWidth}×${first.frameHeight}`);
  if (png.width & (png.width - 1) || png.height & (png.height - 1)) warnings.push(`${id}: ${png.width}×${png.height} is not a power of two (no mipmaps)`);
  const used = new Set<number>();
  for (const state of ANIMATION_STATES) {
    const clip = set[state],
      declared = manifestClips(manifest.enemies[id])[state],
      name = `${id}/${state}`.padEnd(16);
    if (!clip) continue;
    if (!declared) errors.push(`${id}/${state}: registered but not in the manifest`);
    else if (declared.fps !== clip.fps || declared.loop !== clip.loop || declared.frames !== clip.frames || declared.row * manifest.columns !== clip.start)
      errors.push(`${id}/${state}: registry and manifest disagree (row, frames or timing)`);
    const problem = clipError(clip);
    if (problem) errors.push(`${id}/${state}: ${problem}`);
    const n = clip.frames,
      cells = Array.from({ length: n }, (_, i) => cell(png, sheetFrame(clip, i), clip.frameWidth, clip.frameHeight, ANIMATION_COLUMNS)),
      metrics = cells.map(measureArt);
    for (let i = 0; i < n; i++) used.add(sheetFrame(clip, i));
    let drift = 0,
      size = 0,
      minChange = 1;
    metrics.forEach((m, i) => {
      if (m.coverage < 0.002) {
        // A death clip may fade out completely on its last frame; anywhere else an empty cell is broken.
        if (state === "death" && i === n - 1) warnings.push(`${id}/${state}: last frame is empty (fade-out)`);
        else errors.push(`${id}/${state}: frame ${i + 1} is blank`);
      }
      const edge = visibleBorder(cells[i]);
      if (edge > EDGE_ERROR) errors.push(`${id}/${state}: frame ${i + 1} is cut along ${(edge * 100).toFixed(1)} % of its cell border`);
      else if (edge > 0) warnings.push(`${id}/${state}: frame ${i + 1}: visible art on ${(edge * 100).toFixed(1)} % of the cell border`);
      // Soft glow fades out over alpha 1–16 (the aegis sheet carries a faint haze), so the background test counts visible pixels.
      if (m.coverage > 0.8) errors.push(`${id}/${state}: frame ${i + 1} is nearly opaque (no transparent background)`);
      const next = metrics[i + 1] ?? (clip.loop ? metrics[0] : undefined);
      if (!next || next.coverage < 0.002 || m.coverage < 0.002) return;
      drift = Math.max(drift, Math.hypot(next.center.x - m.center.x, next.center.y - m.center.y));
      size = Math.max(size, Math.abs(longest(next) - longest(m)) / longest(m));
      minChange = Math.min(minChange, changed(cells[i], cells[(i + 1) % n]));
    });
    const seam = clip.loop && n > 1 ? Math.hypot(metrics[0].center.x - metrics[n - 1].center.x, metrics[0].center.y - metrics[n - 1].center.y) : NaN;
    // Only idle and move need a stable pivot; hurt recoils and death breaks apart on purpose.
    if (clip.loop) {
      if (drift > DRIFT_ERROR) errors.push(`${id}/${state}: the pivot jumps ${drift.toFixed(3)} of the cell between frames`);
      else if (drift > DRIFT_WARN) warnings.push(`${id}/${state}: pivot drift up to ${drift.toFixed(3)} of the cell between frames`);
      if (size > SIZE_WARN) warnings.push(`${id}/${state}: visible size changes up to ${(size * 100).toFixed(0)} % between frames`);
      if (minChange < 0.001) warnings.push(`${id}/${state}: two neighbouring frames are identical`);
    }
    // The resting body: union of the idle frames (move adds thrust), the reference for placement and size.
    if (state === "idle")
      for (const m of metrics) {
        if (m.coverage < 0.002) continue;
        const u = (union[id] ??= { x0: m.bounds.x0, y0: m.bounds.y0, x1: m.bounds.x1, y1: m.bounds.y1, size: clip.frameWidth });
        u.x0 = Math.min(u.x0, m.bounds.x0);
        u.y0 = Math.min(u.y0, m.bounds.y0);
        u.x1 = Math.max(u.x1, m.bounds.x1);
        u.y1 = Math.max(u.y1, m.bounds.y1);
      }
    const avg = (f: (m: ArtMetrics) => number) => metrics.reduce((t, m) => t + f(m), 0) / Math.max(1, n);
    console.log(
      `${name}${String(n).padStart(4)}  ${clip.frameWidth}×${clip.frameHeight}  ${avg((m) => m.visibleWidth).toFixed(2)}×${avg((m) => m.visibleHeight).toFixed(2)}         ${f2(avg((m) => m.boundsCenter.x))}  ${f2(avg((m) => m.boundsCenter.y))}  ${avg((m) => m.coverage).toFixed(2)}   ${Math.max(...cells.map(visibleBorder)).toFixed(3)}   ${drift.toFixed(3)}      ${(size * 100).toFixed(0).padStart(3)} %    ${Number.isNaN(seam) ? "  -  " : seam.toFixed(3)}  ${(minChange * 100).toFixed(1)} %`,
    );
    if (args.includes("--frames"))
      metrics.forEach((m, i) => console.log(`    frame ${i + 1}: ${m.visibleWidth.toFixed(2)}×${m.visibleHeight.toFixed(2)} ctr ${f2(m.boundsCenter.x)} ${f2(m.boundsCenter.y)} cover ${m.coverage.toFixed(3)} edge ${visibleBorder(cells[i]).toFixed(3)}`));
  }
  // Cells no clip uses must stay empty (a drawn one means a frame count is too low).
  for (let f = 0; f < ANIMATION_COLUMNS * ANIMATION_ROWS; f++)
    if (!used.has(f) && measureArt(cell(png, f, first.frameWidth, first.frameHeight, ANIMATION_COLUMNS)).coverage > 0) errors.push(`${id}: unused cell ${f} is not empty`);
}
console.log(`\nIdentity (idle frames vs the static art of all ${statics.size} types, signature distance):`);
for (const line of identities) console.log(`  ${line}`);
console.log(`\nGame sheets: ${(stored / 1e6).toFixed(1)} MB on disk, ${(decoded / 1e6).toFixed(1)} MB decoded RGBA (GPU textures, ${((decoded * 4) / 3 / 1e6).toFixed(1)} MB with mipmaps).`);
// The battlefield loads only the sheets of the mission's types (`missionAnimationTypes`).
const perSheet = registered.length ? decoded / registered.length : 0,
  missions = DEFAULT_CONTENT.missions.map((m) => ({ id: m.id, n: missionAnimationTypes(m, DEFAULT_CONTENT).size })),
  most = missions.reduce((a, b) => (b.n > a.n ? b : a), { id: "-", n: 0 });
console.log(
  `Per mission: up to ${most.n} sheets (${most.id}), ${((most.n * perSheet) / 1e6).toFixed(1)} MB decoded; mean ${(missions.reduce((t, m) => t + m.n, 0) / Math.max(1, missions.length)).toFixed(1)} sheets; ${missions.filter((m) => !m.n).length} of ${missions.length} missions load none.`,
);

if (args.includes("--write")) {
  const lines = (Object.entries(union) as [EnemyId, NonNullable<(typeof union)[EnemyId]>][]).map(([id, u]) => {
    const r = (v: number) => Number(v.toFixed(4));
    return `  ${id}: { w: ${r((u.x1 - u.x0) / u.size)}, h: ${r((u.y1 - u.y0) / u.size)}, x: ${r((u.x0 + u.x1) / 2 / u.size - 0.5)}, y: ${r((u.y0 + u.y1) / 2 / u.size - 0.5)} },`;
  });
  writeFileSync(
    BOUNDS_FILE,
    `// Generated by scripts/audit-enemy-animations.ts -- --write. Do not edit by hand.\nimport type { EnemyId } from "../core/types";\nimport type { ArtBounds } from "./enemy-art";\n/** Visible bounds of the resting body (union of the idle frames) as a share of the animation cell. */\nexport const ANIMATION_BOUNDS: Readonly<Partial<Record<EnemyId, ArtBounds>>> = {\n${lines.join("\n")}\n};\n`,
  );
  console.log(`wrote ${BOUNDS_FILE.pathname}`);
}
for (const w of warnings) console.log(`WARN  ${w}`);
for (const e of errors) console.log(`ERROR ${e}`);
if (errors.length) process.exit(1);
